// Interface defined in service layer (high-level module owns this)
public interface UserRepository {
    Optional<User> findById(Long id);
    void save(User user);
}

// Implementation in repository layer (low-level module implements interface)
@Repository
public class JpaUserRepository implements UserRepository {
    public Optional<User> findById(Long id) {
        // JPA logic to query database
        return Optional.of(new User(id, "Alice"));
    }
    public void save(User user) { /* persist to DB */ }
}

// High-level service depends on interface only
@Service
public class UserService {
    private final UserRepository userRepository; // interface type, not JpaUserRepository

    // Constructor injection - Spring provides the implementation
    public UserService(UserRepository userRepository) {
        this.userRepository = userRepository;
    }

    public User registerUser(Long id) {
        var user = userRepository.findById(id).orElseThrow();
        // business logic here
        userRepository.save(user);
        return user; // UserService never knows about JpaUserRepository
    }
}

